"use client";

import { motion } from "motion/react";
import { useEffect, useState } from "react";

const slides = [
  { title: "Design at the speed of thought", bg: "from-indigo-600 to-purple-600" },
  { title: "Ship with confidence", bg: "from-sky-700 to-cyan-600" },
  { title: "Accessible by default", bg: "from-rose-700 to-orange-600" },
];

export function CarouselTailwind() {
  const [i, setI] = useState(0);
  const [paused, setPaused] = useState(false);
  const go = (n: number) => setI((n + slides.length) % slides.length);
  useEffect(() => { if (paused) return; const t = setTimeout(() => go(i + 1), 4500); return () => clearTimeout(t); }, [i, paused]);
  return (
    <section aria-roledescription="carousel" aria-label="Product highlights" className="w-full max-w-2xl" onPointerEnter={() => setPaused(true)} onPointerLeave={() => setPaused(false)} onFocus={() => setPaused(true)} onBlur={() => setPaused(false)}>
      <div className="relative h-80 overflow-hidden rounded-2xl border border-zinc-800">
        <motion.div className="flex h-full" animate={{ x: `${-i * 100}%` }} transition={{ type: "spring", stiffness: 260, damping: 32 }} drag="x" dragConstraints={{ left: 0, right: 0 }} onDragEnd={(_, info) => { if (info.offset.x < -60) go(i + 1); else if (info.offset.x > 60) go(i - 1); }} aria-live={paused ? "polite" : "off"}>
          {slides.map((s, n) => (
            <div key={s.title} role="group" aria-roledescription="slide" aria-label={`${n + 1} of ${slides.length}`} aria-hidden={n !== i} className={`flex h-full w-full shrink-0 items-end bg-gradient-to-br p-8 ${s.bg}`}>
              <h3 className="text-3xl font-semibold text-white">{s.title}</h3>
            </div>
          ))}
        </motion.div>
        <button aria-label="Previous slide" onClick={() => go(i - 1)} className="absolute left-3 top-1/2 size-9 -translate-y-1/2 rounded-full bg-black/40 text-white focus-visible:outline-2 focus-visible:outline-zinc-200">&#8249;</button>
        <button aria-label="Next slide" onClick={() => go(i + 1)} className="absolute right-3 top-1/2 size-9 -translate-y-1/2 rounded-full bg-black/40 text-white focus-visible:outline-2 focus-visible:outline-zinc-200">&#8250;</button>
      </div>
      <div className="mt-3 flex justify-center gap-1.5">
        {slides.map((s, n) => <button key={s.title} aria-label={`Go to slide ${n + 1}`} aria-current={n === i} onClick={() => setI(n)} className={`h-2 rounded-full transition-all ${n === i ? "w-7 bg-indigo-500" : "w-2 bg-zinc-600"}`} />)}
      </div>
    </section>
  );
}
